// НЕ ПРОВЕРЕН В ЖИВОМ БРАУЗЕРЕ: подмена ответа через page.route была недоступна при генерации.
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

test.describe('שיעורי תורה', () => {
  test('TL-01 Пустой список (подмена ответа) #6a86f7fc @prod-safe', async ({ page }) => {
    // 1. До перехода: подменить GET rest/v1/content_items пустым списком.
    await page.route('**/rest/v1/content_items**', (route) => {
      if (route.request().method() !== 'GET') return route.continue();
      return route.fulfill({ json: [] });
    });

    // 2. Открыть `/lessons`.
    await page.goto('/lessons');
    await expect(
      page.getByText('אין עדיין שיעורי תורה להצגה. מקור השיעורים ומי שמאשר אותם עדיין לא נקבעו, ולכן המדור אינו מציג תוכן שלא אושר.'),
    ).toBeVisible({ timeout: 20_000 });
  });
});
